// Maximum line length (S8c): no analyzer enforces it, so this script does, for C# files and the prose of Markdown files.
// Run by `just pr-check` and by the "Code is formatted" check of the CI; the tests next to it pin what counts.
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

/** The longest line allowed, in characters (Unicode code points). */
export const MAX_LENGTH = 150;

// Generated or third-party files: their authors are tools, not us.
const SKIPPED = [/(^|\/)(bin|obj|node_modules)\//, /\.g\.cs$/, /\.generated\.cs$/, /\.Designer\.cs$/, /ModelSnapshot\.cs$/, /(^|\/)CHANGELOG\.md$/];

const URL = /https?:\/\/\S+/g;
const FENCE = /^\s*(`{3,}|~{3,})/;

/**
 * Whether a path is a hand-written C# or Markdown file.
 * @param {string} path
 */
export function isChecked(path) {
  return /\.(cs|md)$/.test(path) && !SKIPPED.some((pattern) => pattern.test(path));
}

/**
 * The lines of a file over the limit. In Markdown only prose counts: YAML front matter, fenced code, table rows and the
 * overflow a bare URL causes are left alone, because they are metadata or cannot be wrapped.
 * @param {string} path
 * @param {string} text
 * @returns {{ line: number, length: number }[]}
 */
export function findLongLines(path, text) {
  const markdown = path.endsWith('.md');
  if (!markdown && /<auto-generated/.test(text.slice(0, 500))) {
    return [];
  }

  const found = [];
  let fence = null;
  let frontMatter = false;
  text.split('\n').forEach((raw, index) => {
    const line = raw.replace(/\r$/, '');
    if (markdown) {
      if ((index === 0 && line === '---') || frontMatter) {
        frontMatter = !(frontMatter && line === '---');
        return;
      }
      const opening = FENCE.exec(line);
      if (fence) {
        const closes = opening && opening[1][0] === fence[0] && opening[1].length >= fence.length && line.trim() === opening[1];
        fence = closes ? null : fence;
        return;
      }
      if (opening) {
        fence = opening[1];
        return;
      }
      if (line.trimStart().startsWith('|')) {
        return;
      }
    }

    const length = [...(markdown ? line.replace(URL, '') : line)].length;
    if (length > MAX_LENGTH) {
      found.push({ line: index + 1, length: [...line].length });
    }
  });
  return found;
}

/** The files to check: the given paths, or every tracked and untracked (not ignored) file of the repository. */
function filesToCheck(args) {
  if (args.length > 0) {
    return args;
  }
  return execFileSync('git', ['ls-files', '--cached', '--others', '--exclude-standard'], { encoding: 'utf8' }).split('\n').filter(Boolean);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  let failures = 0;
  for (const path of filesToCheck(process.argv.slice(2)).filter((file) => isChecked(file) && existsSync(file))) {
    for (const { line, length } of findLongLines(path, readFileSync(path, 'utf8'))) {
      console.error(`${path}:${line}: ${length} characters, the limit is ${MAX_LENGTH}`);
      failures++;
    }
  }

  if (failures > 0) {
    console.error(`${failures} line(s) over ${MAX_LENGTH} characters: wrap them`);
    process.exit(1);
  }
  console.log(`No line over ${MAX_LENGTH} characters.`);
}
